// WWXRP balance + Daily Incinerator burn footer for the Side Bets panel.
//
// The token used to live in the Community Coinflip's Protocol Coins drawer.
// It is still a side wager, however, so this component keeps the familiar
// balance/BURN treatment while owning its reads, account scope, and popup form.

import { readFlipWidgetBalances } from '../app/coinflip.js';
import { TX_CONFIRMED_EVENT } from '../app/contracts.js';
import {
  deriveCanSign,
  get,
  getViewedAddress,
  subscribe,
} from '../app/store.js';
import { burnWwxrp, MIN_WWXRP_BURN_WEI } from '../app/wwxrp.js';
import { compactUiError } from '../app/ui-error.js';
import { registerComponentPoll } from '../app/component-poll.js';
import { openPanelPopup, closePanelPopup } from '../app/panel-popups.js';
import './boon-product-indicator.js';

const TOKEN_WEI = 10n ** 18n;
const POLL_MS = 30_000;
const SLIDER_STEPS = 10_000n;

let _readBalances = readFlipWidgetBalances;
let _burn = burnWwxrp;

function _address(value) {
  const normalized = String(value || '').trim().toLowerCase();
  return normalized || null;
}

/** Parse a decimal WWXRP input without crossing through floating point. */
export function parseWwxrpAmount(value) {
  const match = /^\s*(\d+)(?:\.(\d{0,18}))?\s*$/.exec(String(value ?? ''));
  if (!match) return null;
  const fraction = String(match[2] || '').padEnd(18, '0');
  try {
    return (BigInt(match[1]) * TOKEN_WEI) + BigInt(fraction || '0');
  } catch (_e) {
    return null;
  }
}

function _amountInput(value) {
  let raw;
  try { raw = BigInt(value ?? 0); } catch (_e) { raw = 0n; }
  if (raw < 0n) raw = 0n;
  const whole = raw / TOKEN_WEI;
  const fraction = String(raw % TOKEN_WEI).padStart(18, '0').replace(/0+$/, '');
  return fraction ? `${whole}.${fraction}` : String(whole);
}

/** Keep the narrow footer readable while retaining three useful figures. */
export function formatWwxrpBalance(value) {
  let raw;
  try { raw = BigInt(value ?? 0); } catch (_e) { return '—'; }
  if (raw < 0n) raw = -raw;
  if (raw > 0n && raw < TOKEN_WEI) return '<1';
  const whole = raw / TOKEN_WEI;
  if (whole < 1_000n) return whole.toLocaleString('en-US');

  const tiers = [
    [10n ** 15n, 'Q'],
    [10n ** 12n, 'T'],
    [10n ** 9n, 'B'],
    [10n ** 6n, 'M'],
    [10n ** 3n, 'K'],
  ];
  let tierIndex = tiers.findIndex(([scale]) => whole >= scale);
  if (tierIndex < 0) tierIndex = tiers.length - 1;

  for (;;) {
    const [scale, suffix] = tiers[tierIndex];
    const scaledWhole = whole / scale;
    const decimals = scaledWhole >= 100n ? 0 : scaledWhole >= 10n ? 1 : 2;
    const factor = 10n ** BigInt(decimals);
    const rounded = ((whole * factor) + (scale / 2n)) / scale;
    if (rounded >= (1_000n * factor) && tierIndex > 0) {
      tierIndex -= 1;
      continue;
    }
    const integer = rounded / factor;
    const fraction = decimals === 0
      ? ''
      : String(rounded % factor).padStart(decimals, '0').replace(/0+$/, '');
    return `${integer.toLocaleString('en-US')}${fraction ? `.${fraction}` : ''}${suffix}`;
  }
}

function _setWriteLock(button, locked, reason = '') {
  if (!button) return;
  button.disabled = Boolean(locked);
  if (locked) {
    button.setAttribute('data-write-locked', '');
    button.setAttribute('data-write-lock-title', reason);
    button.title = reason;
  } else {
    button.removeAttribute('data-write-locked');
    button.removeAttribute('data-write-lock-title');
    button.removeAttribute('title');
  }
}

class AppWwxrpBurn extends HTMLElement {
  #initialized = false;
  #unsubs = [];
  #poll = null;
  #txListener = null;
  #refreshQueued = false;
  #seq = 0;
  #address = null;
  #balance = null;
  #busy = false;

  connectedCallback() {
    if (this.#initialized) return;
    this.#initialized = true;
    this.#renderShell();
    this.#wire();

    for (const key of ['connected.address', 'viewing.address']) {
      this.#unsubs.push(subscribe(key, () => this.#onIdentityChange()));
    }
    for (const key of ['ui.mode', 'ui.chainOk']) {
      this.#unsubs.push(subscribe(key, () => this.#render()));
    }
    this.#poll = registerComponentPoll(() => this.#refresh(), POLL_MS);
    if (typeof document !== 'undefined') {
      this.#txListener = () => this.#queueRefresh();
      document.addEventListener?.(TX_CONFIRMED_EVENT, this.#txListener);
    }
    this.#onIdentityChange();
  }

  disconnectedCallback() {
    closePanelPopup('incinerator', { restoreFocus: false });
    for (const unsubscribe of this.#unsubs) {
      try { unsubscribe(); } catch (_e) { /* defensive */ }
    }
    this.#unsubs = [];
    if (typeof this.#poll === 'function') this.#poll();
    if (this.#txListener && typeof document !== 'undefined') {
      document.removeEventListener?.(TX_CONFIRMED_EVENT, this.#txListener);
    }
    this.#poll = null;
    this.#txListener = null;
    this.#refreshQueued = false;
    this.#seq += 1;
    this.#initialized = false;
  }

  #renderShell() {
    this.hidden = true;
    this.innerHTML = `
      <div class="incinerator-summary" aria-label="Daily Incinerator">
        <img class="incinerator-summary__badge" src="/shared/coinflip-face-red.svg"
             width="28" height="28" alt="" aria-hidden="true">
        <span class="incinerator-summary__balance" title="Available WWXRP">
          <b data-bind="wwxrp-summary-balance">—</b><small>WWXRP</small>
        </span>
        <button type="button" class="secondary-action" data-bind="wwxrp-open"
                aria-haspopup="dialog" aria-expanded="false" aria-controls="panel-incinerator"
                aria-label="Enter the Daily Incinerator">ENTER INCINERATOR</button>
      </div>
      <section class="panel-popup secondary-popup" id="panel-incinerator" data-panel-popup="incinerator"
               data-bind="wwxrp-dialog" hidden role="dialog" aria-modal="true" aria-labelledby="incinerator-title">
        <div class="panel-popup__window">
          <header class="panel-popup__header">
            <h2 id="incinerator-title">DAILY INCINERATOR</h2>
            <button type="button" class="panel-popup__close" data-panel-close aria-label="Close Incinerator">×</button>
          </header>
          <div class="panel-popup__body">
            <p class="secondary-popup__intro incinerator-prizes">Burn WWXRP for a chance to win <strong>10,000 FLIP</strong> or a <strong>100,000 FLIP jackpot</strong>.</p>
            <p class="incinerator-note">Prizes are credited to Community Coinflip. Minimum burn: 25 WWXRP. Burned tokens are permanently spent.</p>
            <section class="pari-wwxrp pari-funding-card pari-funding-card--wwxrp" data-bind="wwxrp-shell"
                     aria-label="WWXRP balance and Daily Incinerator entry">
              <span class="pari-wwxrp__mark pari-funding-card__mark" aria-hidden="true">
                <img src="/shared/coinflip-face-red.svg" alt="">
              </span>
              <span class="pari-wwxrp__identity pari-funding-card__identity">
                <small>DAILY INCINERATOR</small>
                <strong>WWXRP</strong>
                <span class="pari-wwxrp__balance pari-funding-card__balance" data-bind="wwxrp-balance-wrap">
                  <small>AVAILABLE</small>
                  <strong><span data-bind="wwxrp-balance">—</span></strong>
                </span>
              </span>
              <span class="pari-wwxrp__amount pari-funding-card__amount">
                <small>BURN AMOUNT</small>
                <span class="pari-wwxrp__amount-control pari-funding-card__amount-control">
                  <input type="text" data-bind="wwxrp-amount" inputmode="decimal"
                         autocomplete="off" spellcheck="false" aria-label="WWXRP to burn">
                  <span class="pari-wwxrp__unit pari-funding-card__unit">WWXRP</span>
                  <button type="button" data-bind="wwxrp-max">MAX</button>
                </span>
              </span>
              <button type="button" class="pari-wwxrp__burn pari-funding-card__action" data-write data-write-locked
                      data-write-lock-title="WWXRP balance is loading"
                      data-bind="wwxrp-burn">
                <b data-bind="wwxrp-burn-label">BURN</b>
                <!-- WWXRP boons (38/39/40) are spent by this burn (WWXRP.enter). -->
                <boon-product-indicator product="degenerette-wwxrp"></boon-product-indicator>
              </button>
              <div class="incinerator-range">
                <input type="range" min="0" max="10000" step="1" value="0"
                       data-bind="wwxrp-slider" aria-label="WWXRP burn amount">
                <div class="incinerator-range__limits"><span>25 WWXRP</span><span data-bind="wwxrp-slider-max">— WWXRP</span></div>
              </div>
              <p class="pari-wwxrp__feedback pari-funding-card__feedback" data-bind="wwxrp-feedback"
                 hidden role="status"></p>
            </section>
          </div>
        </div>
      </section>
    `;
    const input = this.querySelector('[data-bind="wwxrp-amount"]');
    if (input) input.value = '25';
  }

  #wire() {
    const trigger = this.querySelector('[data-bind="wwxrp-open"]');
    trigger?.addEventListener('click', () => {
      openPanelPopup('incinerator', trigger, this.querySelector('[data-bind="wwxrp-dialog"]'));
      trigger.setAttribute('aria-expanded', 'true');
    });
    this.querySelector('[data-bind="wwxrp-dialog"]')?.addEventListener('app:panel-close', () => {
      trigger?.setAttribute('aria-expanded', 'false');
    });
    this.querySelector('[data-bind="wwxrp-burn"]')
      ?.addEventListener('click', () => { void this.#submit(); });
    this.querySelector('[data-bind="wwxrp-max"]')
      ?.addEventListener('click', () => this.#setMax());
    const input = this.querySelector('[data-bind="wwxrp-amount"]');
    input?.addEventListener('input', () => this.#render());
    this.querySelector('[data-bind="wwxrp-slider"]')?.addEventListener('input', (event) => {
      if (this.#busy || this.#balance == null || this.#balance <= MIN_WWXRP_BURN_WEI || !input) return;
      const position = BigInt(Math.max(0, Math.min(Number(SLIDER_STEPS), Math.round(Number(event.target.value) || 0))));
      const span = this.#balance - MIN_WWXRP_BURN_WEI;
      input.value = _amountInput(MIN_WWXRP_BURN_WEI + span * position / SLIDER_STEPS);
      this.#render();
    });
    input?.addEventListener('keydown', (event) => {
      if (event?.key === 'Enter') void this.#submit();
    });
  }

  #onIdentityChange() {
    const next = _address(getViewedAddress());
    if (next !== this.#address) {
      closePanelPopup('incinerator', { restoreFocus: false });
      this.#seq += 1;
      this.#address = next;
      this.#balance = null;
      this.#setFeedback('');
    }
    this.#render();
    this.#queueRefresh();
  }

  #queueRefresh() {
    if (!this.#initialized || this.#refreshQueued) return;
    this.#refreshQueued = true;
    queueMicrotask(() => {
      this.#refreshQueued = false;
      if (this.#initialized) void this.#refresh();
    });
  }

  async #refresh() {
    const target = _address(getViewedAddress());
    if (target !== this.#address) {
      this.#address = target;
      this.#balance = null;
      this.#seq += 1;
      this.#render();
    }
    if (!target) return;
    const seq = ++this.#seq;
    let snapshot;
    try { snapshot = await _readBalances({ player: target }); }
    catch (_e) { return; }
    if (seq !== this.#seq || target !== this.#address) return;
    if (snapshot?.wwxrpBalance != null) {
      try { this.#balance = BigInt(snapshot.wwxrpBalance); }
      catch (_e) { this.#balance = null; }
    } else {
      this.#balance = null;
    }
    this.#render();
  }

  #canWrite() {
    const connected = _address(get('connected.address'));
    return Boolean(
      connected
      && connected === this.#address
      && get('ui.mode') === 'self'
      && deriveCanSign()
    );
  }

  #lockReason() {
    if (this.#busy) return 'Transaction in progress';
    if (!this.#address) return 'Connect a wallet first';
    if (!this.#canWrite()) return 'Open your own wallet view to incinerate WWXRP';
    if (this.#balance == null) return 'WWXRP balance is loading';
    if (this.#balance < MIN_WWXRP_BURN_WEI) return 'Minimum burn is 25 WWXRP';
    return '';
  }

  #render() {
    this.hidden = !this.#address || this.#balance == null || this.#balance <= 0n;
    if (this.hidden) closePanelPopup('incinerator', { restoreFocus: false });
    const shell = this.querySelector('[data-bind="wwxrp-shell"]');
    if (shell) shell.hidden = this.hidden;

    const balance = this.querySelector('[data-bind="wwxrp-balance"]');
    const balanceWrap = this.querySelector('[data-bind="wwxrp-balance-wrap"]');
    if (balance) balance.textContent = this.#balance == null
      ? '—'
      : formatWwxrpBalance(this.#balance);
    const summaryBalance = this.querySelector('[data-bind="wwxrp-summary-balance"]');
    if (summaryBalance) summaryBalance.textContent = this.#balance == null
      ? '—'
      : formatWwxrpBalance(this.#balance);
    if (balanceWrap) {
      const exact = this.#balance == null ? '' : `${_amountInput(this.#balance)} WWXRP`;
      balanceWrap.title = exact;
      if (exact) balanceWrap.setAttribute('aria-label', `WWXRP balance: ${exact}`);
      else balanceWrap.removeAttribute('aria-label');
    }

    const burn = this.querySelector('[data-bind="wwxrp-burn"]');
    const burnLabel = this.querySelector('[data-bind="wwxrp-burn-label"]');
    const lockReason = this.#lockReason();
    if (burnLabel) burnLabel.textContent = this.#busy ? 'WAIT' : 'BURN';

    const input = this.querySelector('[data-bind="wwxrp-amount"]');
    const amount = parseWwxrpAmount(input?.value);
    const valid = amount != null
      && amount >= MIN_WWXRP_BURN_WEI
      && this.#balance != null
      && amount <= this.#balance;
    if (input) {
      if (input.value && !valid) input.setAttribute('aria-invalid', 'true');
      else input.removeAttribute('aria-invalid');
      input.disabled = this.#busy;
    }
    _setWriteLock(
      burn,
      Boolean(lockReason) || !valid,
      lockReason || 'Enter an amount from 25 through your WWXRP balance',
    );
    const max = this.querySelector('[data-bind="wwxrp-max"]');
    if (max) max.disabled = this.#busy || this.#balance == null;
    const slider = this.querySelector('[data-bind="wwxrp-slider"]');
    if (slider) {
      const span = (this.#balance ?? 0n) - MIN_WWXRP_BURN_WEI;
      const clamped = amount == null || amount < MIN_WWXRP_BURN_WEI
        ? MIN_WWXRP_BURN_WEI : amount > this.#balance ? this.#balance : amount;
      // Round to the nearest step so a keyboard increment keeps its position
      // after the exact token amount is converted back to a slider value.
      const position = span > 0n
        ? ((clamped - MIN_WWXRP_BURN_WEI) * SLIDER_STEPS + span / 2n) / span : 0n;
      slider.value = String(position);
      slider.disabled = this.#busy || span <= 0n;
      slider.setAttribute('aria-valuetext', `${_amountInput(span > 0n ? clamped : MIN_WWXRP_BURN_WEI)} WWXRP`);
    }
    const sliderMax = this.querySelector('[data-bind="wwxrp-slider-max"]');
    if (sliderMax) {
      sliderMax.textContent = `${this.#balance == null ? '—' : formatWwxrpBalance(this.#balance)} WWXRP`;
      sliderMax.title = this.#balance == null ? '' : `${_amountInput(this.#balance)} WWXRP`;
    }
  }

  #setMax() {
    if (this.#balance == null) return;
    const input = this.querySelector('[data-bind="wwxrp-amount"]');
    if (!input) return;
    input.value = _amountInput(this.#balance);
    this.#render();
  }

  #setFeedback(message, { error = false } = {}) {
    const node = this.querySelector('[data-bind="wwxrp-feedback"]');
    if (!node) return;
    node.textContent = String(message || '');
    node.hidden = !message;
    if (error) node.setAttribute('data-state', 'error');
    else node.removeAttribute('data-state');
  }

  async #submit() {
    if (this.#busy || !this.#canWrite()) return;
    const input = this.querySelector('[data-bind="wwxrp-amount"]');
    const amount = parseWwxrpAmount(input?.value);
    if (amount == null || amount < MIN_WWXRP_BURN_WEI) {
      this.#setFeedback('Minimum burn is 25 WWXRP.', { error: true });
      return;
    }
    if (this.#balance == null || amount > this.#balance) {
      this.#setFeedback('Not enough WWXRP for that burn.', { error: true });
      return;
    }

    const target = this.#address;
    this.#busy = true;
    this.#setFeedback('');
    this.#render();
    try {
      await _burn({ amount });
      if (target !== this.#address) return;
      if (this.#balance != null) this.#balance -= amount;
      this.#setFeedback(`${formatWwxrpBalance(amount)} WWXRP INCINERATED`);
      this.#queueRefresh();
    } catch (error) {
      if (target === this.#address) {
        this.#setFeedback(
          compactUiError(error, 'WWXRP incineration did not go through.'),
          { error: true },
        );
      }
    } finally {
      this.#busy = false;
      this.#render();
    }
  }
}

if (typeof customElements !== 'undefined' && !customElements.get('app-wwxrp-burn')) {
  customElements.define('app-wwxrp-burn', AppWwxrpBurn);
}

/** Test-only dependency seam. */
export function __setWwxrpBurnWidgetDepsForTest({ balances, burn } = {}) {
  if (typeof balances === 'function') _readBalances = balances;
  if (typeof burn === 'function') _burn = burn;
}

/** Test-only dependency reset. */
export function __resetWwxrpBurnWidgetDepsForTest() {
  _readBalances = readFlipWidgetBalances;
  _burn = burnWwxrp;
}
